def put(table, key, value):
    chain = table[bucket(key, len(table))]
    for pair in chain:
        if pair[0] == key:
            pair[1] = value
            return
    chain.append([key, value])

def get(table, key):
    for k, v in table[bucket(key, len(table))]:
        if k == key:
            return v
    return None

